#!/usr/bin/env python3# scripts/validate_subact.py — Изолированная валидация ПодАкта (Γ_Locality compliant)import sys, os, yaml, subprocess, jsonfrom pathlib import Pathdef load_subact_config(subact_path):    """Загружает конфиг ПодАкта"""    with open(subact_path, encoding="utf-8") as f:        return yaml.safe_load(f)def run_validation_pipeline(subact_path):    """Запускает TS-Validator Layer 1-4 для ПодАкта"""    cmd = ["./scripts/run_full_validation_pipeline.sh", "--subact", subact_path]    result = subprocess.run(cmd, capture_output=True, text=True, cwd=os.getcwd())    return {        "stdout": result.stdout,        "stderr": result.stderr,        "returncode": result.returncode,        "passed": "✅ КОНТУР ЗАКРЫТ" in result.stdout or result.returncode == 0    }def get_baseline_from_registry(subact_id, domain="physics_2.0"):    """Берёт baseline Γ_t из registry/index.json (B-уровень)"""    registry_path = Path("registry/index.json")    if not registry_path.exists():        return None    with open(registry_path, encoding="utf-8") as f:        registry = json.load(f)    for entry in registry.get("entries", []):        if entry.get("act_id") == subact_id and entry.get("status") == "validated":            metrics = entry.get("metrics", {})            return metrics.get("baseline_gamma", 0.0)    return Nonedef get_baseline_from_neo4j(event_id, driver_config):    """Берёт baseline Γ_t из последнего узла в Neo4j (если доступен)"""    try:        from neo4j import GraphDatabase, basic_auth        driver = GraphDatabase.driver(            driver_config["uri"],            auth=basic_auth(driver_config["user"], driver_config["password"])        )        with driver.session() as session:            query = """            MATCH (e:TS_Event {event_id: $event_id})            RETURN e.current_gamma as baseline            ORDER BY e.updated DESC            LIMIT 1            """            result = session.run(query, event_id=event_id)            record = result.single()            driver.close()            return record["baseline"] if record else None    except Exception:        return None  # Fallback to registry or defaultdef validate_and_report(subact_path, event_id="sc_coherence_001"):    """Полный цикл: валидация → baseline → отчёт"""    print(f"🔍 Валидация ПодАкта: {subact_path}")        # 1. Загружаем конфиг    config = load_subact_config(subact_path)    subact_id = config.get("subact_id", config.get("act_id"))    status = config.get("status", "template")        # 2. Проверяем статус (быстрая проверка)    if status != "validated":        print(f"⚠️  ПодАкт имеет статус '{status}'. Требуется 'validated' для вычисления ΔΓ.")        print("📜 Запускаем валидацию...")        # 3. Запускаем TS-Validator Layer 1-4    validation = run_validation_pipeline(subact_path)    if not validation["passed"]:        print(f"❌ Валидация не пройдена:\n{validation['stderr']}")        return {"valid": False, "error": "validation_failed"}    print("✅ Валидация пройдена (Layer 1-4 PASS)")        # 4. Получаем baseline (приоритет: Neo4j → registry → default)    baseline = None        # Попытка из Neo4j    try:        from neo4j import GraphDatabase, basic_auth        driver_config = {"uri": "bolt://localhost:7687", "user": "neo4j", "password": "password"}        baseline = get_baseline_from_neo4j(event_id, driver_config)        if baseline is not None:            print(f"📊 Baseline из Neo4j: {baseline:.3f}")    except ImportError:        pass        # Fallback на registry    if baseline is None:        baseline = get_baseline_from_registry(subact_id)        if baseline is not None:            print(f"📊 Baseline из registry: {baseline:.3f}")        # Fallback на default    if baseline is None:        baseline = 0.0        print(f"⚠️  Baseline не найден, используем default: {baseline:.3f}")        # 5. Вычисляем ΔΓ (T_HP.1: только на validated акте)    current_gamma = config.get("metrics", {}).get("delta_gamma_x", 0.645)    epsilon = config.get("metrics", {}).get("epsilon_x", 0.375)    delta_gamma = round(current_gamma - baseline, 4)    valid = delta_gamma > epsilon        print(f"📊 Γ_t: {baseline:.3f} → Γ_t+1: {current_gamma:.3f}")    print(f"📊 ΔΓ: {delta_gamma:.3f} | ε: {epsilon:.3f} | Valid: {valid}")        return {        "valid": True,        "subact_id": subact_id,        "baseline_gamma": baseline,        "current_gamma": current_gamma,        "delta_gamma": delta_gamma,        "epsilon": epsilon,        "valid_binding": valid,        "ts_clock": f"τ_{subact_id}_001"    }if __name__ == "__main__":    if len(sys.argv) < 2:        print("Использование: python3 scripts/validate_subact.py <path_to_subact.yaml>")        sys.exit(1)        subact_path = sys.argv[1]    result = validate_and_report(subact_path)        # Сохраняем отчёт    os.makedirs("output", exist_ok=True)    with open("output/validation_report.json", "w") as f:        json.dump(result, f, indent=2)    print(f"💾 Отчёт: output/validation_report.json")        sys.exit(0 if result["valid"] else 1)